#pragma once
#include "PostEffects.h"
template<class P> static PostSettings postSettings(const P& p){PostSettings f;f.kind=choice(p,POST_KIND)-1;f.amount=value(p,POST_AMOUNT);f.x=value(p,POST_X)/100;f.y=value(p,POST_Y)/100;f.scale=value(p,POST_SCALE)/100;f.rotation=value(p,POST_ROTATION);f.radius=value(p,POST_RADIUS);f.threshold=value(p,POST_THRESHOLD);f.softness=value(p,POST_SOFTNESS);f.inner=value(p,POST_INNER);f.feather=value(p,POST_FEATHER);f.shift=value(p,POST_SHIFT);f.count=std::clamp(int(value(p,POST_COUNT)),2,8);f.region=checked(p,POST_REGION);f.edge=value(p,POST_EDGE);f.edgeLimit=value(p,POST_EDGE_LIMIT);f.flare=checked(p,FLARE_ENABLED);f.flareGain=value(p,FLARE_GAIN);f.flareThreshold=value(p,FLARE_THRESHOLD);f.flareSources=std::clamp(int(value(p,FLARE_SOURCES)),1,8);
 f.prismType=std::clamp(choice(p,POST_PRISM_TYPE)-1,0,7);f.prismShift=value(p,POST_PRISM_SHIFT);f.edgeBlur=value(p,POST_EDGE_BLUR);f.recovery=value(p,HIGHLIGHT_RECOVERY);f.starGain=value(p,STAR_GAIN);f.starSize=value(p,STAR_SIZE);f.starStreaks=value(p,STAR_STREAKS);
 f.dirtAmount=value(p,DIRT_AMOUNT);f.dirtSeed=value(p,DIRT_SEED);f.dirtFinger=value(p,DIRT_FINGER);f.dirtDust=value(p,DIRT_DUST);f.dirtScratch=value(p,DIRT_SCRATCH);f.dirtFungus=value(p,DIRT_FUNGUS);f.dirtDefocus=value(p,DIRT_DEFOCUS);f.dirtThreshold=value(p,DIRT_THRESHOLD);return f;}
